40	// Per-warp-group register targets for the producer/consumer split (§3.4).
41	// On Hopper setmaxnreg is warp-group granular (128 threads / 4 warps). The
42	// fused kernel launches 256 threads = TWO warp-groups so the split is well
43	// formed: warp-group 0 is the PRODUCER (staging / queue / row-context loads,
44	// few registers) and warp-group 1 is the CONSUMER (the heavy WGMMA-class
45	// compute + optimizer tail). Partitioning lets the consumer claim a large
46	// register file WITHOUT the producer's allocation counting against the L3
47	// footprint, so no single warp-group needs the full fused register budget.
48	static constexpr int kProducerRegsF = 32;
49	static constexpr int kConsumerRegsF = 200;
50	// Warp-group size on Hopper (threads). 256-thread block => 2 warp-groups.
51	static constexpr int kWarpGroupThreads = 128;
52	static constexpr int kFusedBlockThreads = 256;
53	
54	// =========================================================================
55	//  Optimizer stage — the fused tail. Pulls tensors from the queue and applies
56	//  the REAL apply_optimizer<Opt> elementwise over this SM's resident state
57	//  slice (kept L2-warm via the %smid pin, §1.3).
58	// =========================================================================
59	// #6 — per-Opt pointer rebase via `if constexpr`. Rather than unconditionally
60	// bumping all 8 optimizer-state pointers per task (8 predicated adds + the
61	// chance the allocator keeps every field live), only the pointers the CHOSEN
62	// optimizer actually dereferences are rebased to the tensor slice; the rest are
63	// compiled out. `ts` starts as a copy of the const& `st` (the scalar
64	// hyperparams must be present), but the dead-pointer rebases vanish, lowering
65	// the local/register footprint of the tail.
66	template <OptId Opt>
67	__device__ __forceinline__ FusedOptState rebase_state(const FusedOptState& st,
68	                                                       int64_t off) {
69	    FusedOptState ts = st;
70	    if constexpr (Opt == OptId::AdamW || Opt == OptId::Lion ||
71	                  Opt == OptId::Grokfast || Opt == OptId::GrokAdamW ||
72	                  Opt == OptId::LookSAM || Opt == OptId::Prodigy ||
73	                  Opt == OptId::NeuralGrok || Opt == OptId::SuperGrok11 ||
74	                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2) {
75	        if (ts.exp_avg)    ts.exp_avg    += off;   // m (all Adam-family tails)
76	    }
77	    if constexpr (Opt != OptId::Lion && Opt != OptId::Muon) {
78	        if (ts.exp_avg_sq) ts.exp_avg_sq += off;   // v (everyone but Lion/Muon)
79	    }
80	    if constexpr (Opt == OptId::Grokfast || Opt == OptId::GrokAdamW) {
81	        if (ts.ema)        ts.ema        += off;
82	    }
83	    if constexpr (Opt == OptId::Prodigy) {
84	        if (ts.s_track)    ts.s_track    += off;
85	    }
86	    if constexpr (Opt == OptId::SuperGrok11 || Opt == OptId::SuperGrok15) {
87	        if (ts.mu)         ts.mu         += off;
88	    }
89	    if constexpr (Opt == OptId::LookSAM) {
90	        if (ts.sam_dir)    ts.sam_dir    += off;
91	    }
92	    if constexpr (Opt == OptId::Muon) {
93	        if (ts.orth)       ts.orth       += off;
94	    }
95	    if constexpr (Opt == OptId::SuperGrok2) {
96	        if (ts.smart_grad) ts.smart_grad += off;
97	    }
98	    return ts;
99	}
100	
101	template <OptId Opt>
102	__device__ void fused_optimizer_stage(const PersistentContext& ctx,
103	                                       float* __restrict__ params,
104	                                       const float* __restrict__ grad,
105	                                       const int* sizes, const int* offsets,
106	                                       int step, const FusedOptState& st) {
107	    __shared__ int task_slot;
108	    TaskQueue q = ctx.queue();
109	    for (int t = q.next_block(&task_slot); t < ctx.n_tasks;
110	         t = q.next_block(&task_slot)) {
111	        const int n = sizes[t];
112	        // #2 int64: off is the tensor's element offset into the global param
113	        // blob and can exceed 2^31; rebase the slice pointers in 64-bit so the
114	        // base address is correct past 2 Gi elements. The within-tensor index
115	        // (base/i below) is bounded by n (an int) but apply_optimizer takes an
116	        // int64_t idx so the addition never truncates. Behavior-preserving.
117	        const int64_t off = (int64_t)offsets[t];
118	        // #6: rebase only the pointers Opt uses to this tensor's slice.
119	        const FusedOptState ts = rebase_state<Opt>(st, off);
120	        float* __restrict__ p = params + off;
121	        const float* __restrict__ g = grad + off;
122	        // #1 — float4 vectorization of the per-element tail. Each thread strides
123	        // over groups of 4 CONSECUTIVE indices and calls the canonical per-
124	        // element optimizer fn 4× on [4j .. 4j+3]; because the four indices are
125	        // contiguous and the buffers are __restrict__, the loads/stores of
126	        // params/grad/m/v coalesce into 128-bit float4 transactions. The
127	        // canonical algorithm math (csrc/algorithms/<opt>.h via apply_optimizer)
128	        // is CALLED, never re-inlined — only the loop's access pattern changes.
129	        const int n4 = n >> 2;                  // # of full float4 groups
130	        for (int j = threadIdx.x; j < n4; j += blockDim.x) {
131	            const int64_t base = (int64_t)j << 2;   // #2 int64 within-tensor idx
132	            apply_optimizer<Opt>(p, g, base + 0, step, ts);
133	            apply_optimizer<Opt>(p, g, base + 1, step, ts);
134	            apply_optimizer<Opt>(p, g, base + 2, step, ts);
135	            apply_optimizer<Opt>(p, g, base + 3, step, ts);
136	        }
137	        // Scalar tail for the remainder (n not a multiple of 4).
138	        for (int i = (n4 << 2) + (int)threadIdx.x; i < n; i += blockDim.x) {
139	            apply_optimizer<Opt>(p, g, (int64_t)i, step, ts);
140	        }
141	    }
142	}
143	
144	// =========================================================================
145	//  Stage 5 — TRUE cross-phase fusion (bwd→opt), SMEM-resident grad tile.
146	//
147	//  HONEST SCOPE / what is realized vs deferred:
148	//   * REALIZED: the backward grad of a tensor and the optimizer update of the
149	//     SAME tensor are fused into ONE queue-pulled body. The grad is computed
150	//     into a per-CTA __shared__ tile and the optimizer reads it from SMEM — the
151	//     grad NEVER round-trips through the global `grad` buffer, and the grid
152	//     barrier that used to separate bwd from opt is ELIMINATED (3 phases / 2
153	//     barriers → 2 phases / 1 barrier per L3 step). This is correct because
154	//     both the activation backward (grad = acts*act'(param)) and every
155	//     apply_optimizer<Opt> are strictly ELEMENT-LOCAL for a given tensor: no
156	//     cross-element and no cross-tensor dependency couples bwd to opt, so no
157	//     grid-wide sync is needed between them for the same tensor, and the SAME
158	//     CTA owns the tensor end-to-end within one queue pull (no work-stealing
159	//     hand-off can split a tensor's bwd from its opt).
160	//   * STILL GLOBAL (deferred, with reason): the forward `acts` buffer. fwd and
161	//     bwd are split by a grid barrier AND the task queue is reset between them,
162	//     so under work-stealing (§1.2) a different CTA may own a tensor in bwd than
163	//     owned it in fwd. A CTA-local SMEM acts tile therefore CANNOT be carried
164	//     across the fwd→bwd barrier safely. Making acts SMEM-resident would require
165	//     a stable tensor→CTA partition (abandoning work-stealing) or DSMEM cluster
166	//     sharing — out of scope for a no-silicon, behavior-preserving change. So
167	//     acts stays global; that round-trip is documented, not hidden.
168	//   * The apply math is still CALLED via apply_optimizer<Opt> (drift-guard safe);
169	//     only the grad SOURCE pointer changes from global to the SMEM tile, and the
170	//     params/state pointers are rebased per chunk so the canonical algorithm
171	//     addresses the correct global state. 🟡 perf (no silicon to measure).
172	//
173	//  The grad value itself is BIT-IDENTICAL to the previous two-phase path:
174	//  grad = acts[gi] * model_activation_grad<M>(params[gi]) — same expression,
175	//  same operand order; only its storage class (SMEM vs global) changed.
176	// =========================================================================
177	static constexpr int kGradTile = 1024;   // floats per SMEM grad tile (4 KB)
178	
179	template <ModelId M, OptId Opt>
180	__device__ void fused_backward_optimizer_stage(
181	        const PersistentContext& ctx,
182	        float* __restrict__ params,
183	        const float* __restrict__ acts,
184	        const int* sizes, const int* offsets,
185	        int step, const FusedOptState& st) {
186	    __shared__ int task_slot;
187	    __shared__ float smem_grad[kGradTile];
188	    TaskQueue q = ctx.queue();
189	    for (int t = q.next_block(&task_slot); t < ctx.n_tasks;
190	         t = q.next_block(&task_slot)) {
191	        const int n = sizes[t];
192	        const int64_t off = (int64_t)offsets[t];   // #2 int64 base
193	        // Tile the tensor; each tile's grad lives in SMEM, consumed in place by
194	        // the optimizer (no global grad write/read for this tensor).
195	        for (int c0 = 0; c0 < n; c0 += kGradTile) {
196	            const int chunk = (n - c0 < kGradTile) ? (n - c0) : kGradTile;
197	            const int64_t chunk_base = off + c0;
198	            // Backward: compute grad of this chunk into SMEM (element-local).
199	            for (int i = threadIdx.x; i < chunk; i += blockDim.x) {
200	                const int64_t gi = chunk_base + i;
201	                smem_grad[i] = acts[gi] * model_activation_grad<M>(params[gi]);
202	            }
203	            __syncthreads();
204	            // Optimizer: read grad from the SMEM tile. Rebase params + state to
205	            // this chunk so apply_optimizer's chunk-local idx addresses the
206	            // correct global params/m/v while grad comes from SMEM.
207	            const FusedOptState ts = rebase_state<Opt>(st, chunk_base);
208	            float* __restrict__ p = params + chunk_base;
209	            const float* __restrict__ g = smem_grad;   // SMEM-resident grad
210	            const int n4 = chunk >> 2;
211	            for (int j = threadIdx.x; j < n4; j += blockDim.x) {
212	                const int64_t base = (int64_t)j << 2;
213	                apply_optimizer<Opt>(p, g, base + 0, step, ts);
214	                apply_optimizer<Opt>(p, g, base + 1, step, ts);
215	                apply_optimizer<Opt>(p, g, base + 2, step, ts);
216	                apply_optimizer<Opt>(p, g, base + 3, step, ts);
217	            }
218	            for (int i = (n4 << 2) + (int)threadIdx.x; i < chunk;
219	                 i += blockDim.x) {
220	                apply_optimizer<Opt>(p, g, (int64_t)i, step, ts);
221	            }
222	            __syncthreads();   // tile reuse: all opt reads done before next fill
223	        }
224	    }
225	}
