317	// LayerNorm forward over the last dim (width=d). Caches xhat + inv_std for bwd.
318	__device__ __forceinline__ void vit_layernorm_fwd(
319	        const float* __restrict__ x, const float* __restrict__ gamma,
320	        const float* __restrict__ beta, float* __restrict__ y,
321	        float* __restrict__ xhat_out, float* __restrict__ inv_out, float* red) {
322	    for (int s = 0; s < vit::kSeq; ++s) {
323	        const float* xr = x + s * vit::kD;
324	        float sum = 0.0f;
325	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) sum += xr[j];
326	        float mean = vit_block_sum(sum, red) / (float)vit::kD;
327	        float vs = 0.0f;
328	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
329	            float c = xr[j] - mean; vs += c * c;
330	        }
331	        float var = vit_block_sum(vs, red) / (float)vit::kD;
332	        float inv = rsqrtf(var + vit::kLnEps);
333	        if (threadIdx.x == 0) inv_out[s] = inv;
334	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
335	            float xh = (xr[j] - mean) * inv;
336	            xhat_out[s * vit::kD + j] = xh;
337	            y[s * vit::kD + j] = xh * gamma[j] + beta[j];
338	        }
339	        __syncthreads();
340	    }
341	}
