628	// ────────────────────────────────────────────────────────────────────────────
629	//  BACKWARD for one sample (CTA-cooperative). Assumes vit_forward_sample has run
630	//  for THIS sample (so layer_in/final_in/fn caches/logits + sm->patch are live).
631	//  Accumulates every weight grad into the CTA's partial buffer `g`.
632	//
633	//  Transcribed from tests/hw/vit_oracle.py::vit_backward (structurally mirrored
634	//  in tests/hw/vit_kernel_mirror.py).
635	// ────────────────────────────────────────────────────────────────────────────
636	__device__ void vit_backward_sample(const VitWeights& w, const VitGrad& g,
637	                                     int target, int B, VitSampleSmem* sm) {
638	    // ── CE backward: dlogits = (softmax - onehot)/B. ──
639	    float lmax = -CUDART_INF_F;
640	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x)
641	        lmax = fmaxf(lmax, sm->logits[o]);
642	    lmax = vit_block_max(lmax, sm->red);
643	    float es = 0.0f;
644	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x)
645	        es += __expf(sm->logits[o] - lmax);
646	    es = vit_block_sum(es, sm->red);
647	    float inv_es = 1.0f / es;
648	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
649	        float sm_o = __expf(sm->logits[o] - lmax) * inv_es;
650	        float dl = (sm_o - ((o == target) ? 1.0f : 0.0f)) / (float)B;
651	        sm->logits[o] = dl;   // overwrite logits[] with dlogits in place
652	    }
653	    __syncthreads();
654	    // ── head (out): logits = hn @ out_w^T + out_b. hn recomputed from the cached
655	    //    final-norm: hn[j] = fn_xhat[0][j]*norm_w[j] + norm_b[j]. ──
656	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
657	        float dl = sm->logits[o];
658	        g.out_b[o] += dl;
659	        float* gwrow = g.out_w + (int64_t)o * vit::kD;
660	        const float* xh = &sm->fn_xhat[0][0];
661	        #pragma unroll 4
662	        for (int j = 0; j < vit::kD; ++j) {
663	            float hn_j = xh[j] * w.norm_w[j] + w.norm_b[j];
664	            gwrow[j] += dl * hn_j;
665	        }
666	    }
667	    __syncthreads();
668	    // dhn[j] (feature-parallel) into dh row 0 scratch.
669	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
670	        float acc = 0.0f;
671	        for (int o = 0; o < vit::kVocab; ++o)
672	            acc += sm->logits[o] * w.out_w[(int64_t)o * vit::kD + j];
673	        sm->dh[0][j] = acc;   // dhn
674	    }
675	    __syncthreads();
676	    // ── final norm backward (single CLS row 0): dy=dhn, xhat=fn_xhat[0],
677	    //    inv=fn_inv[0]. Produces dh into dh[0]; zeros all other rows; accumulate
678	    //    dnorm_w/dnorm_b. Stage dy into ctx row 0. ──
679	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x)
680	        sm->ctx[0][j] = sm->dh[0][j];   // dy at CLS position
681	    __syncthreads();
682	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
683	        float d = sm->ctx[0][j];
684	        float xh = sm->fn_xhat[0][j];
685	        g.norm_b[j] += d; g.norm_w[j] += d * xh;
686	    }
687	    __syncthreads();
688	    {
689	        const float* dyr = &sm->ctx[0][0];
690	        const float* xhr = &sm->fn_xhat[0][0];
691	        float sda = 0.0f, sdax = 0.0f;
692	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
693	            float dxhat = dyr[j] * w.norm_w[j];
694	            sda += dxhat; sdax += dxhat * xhr[j];
695	        }
696	        sda = vit_block_sum(sda, sm->red);
697	        sdax = vit_block_sum(sdax, sm->red);
698	        float inv_s = sm->fn_inv[0];
699	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
700	            float dxhat = dyr[j] * w.norm_w[j];
701	            for (int s = 0; s < vit::kSeq; ++s) sm->dh[s][j] = 0.0f;
702	            sm->dh[0][j] = inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)vit::kD);
703	        }
704	        __syncthreads();
705	    }
706	    // dh now = grad wrt the last layer's OUTPUT [kSeq,d] (only CLS pos 0 nonzero).
707	
708	    // ── per-layer backward (reverse). Each layer: recompute fwd intermediates,
709	    //    then apply the chain. The running adjoint `dh` is preserved across the
710	    //    recompute by SAVING it into final_in (free after fwd) around the
711	    //    recompute (which temporarily uses sm->dh as ff2 scratch). ─────────────
712	    for (int li = vit::kLayers - 1; li >= 0; --li) {
713	        const VitWeights::Layer& L = w.layer[li];
714	        const VitGrad::Layer& G = g.layer[li];
715	        // Save incoming adjoint dh into final_in — recompute clobbers sm->dh.
716	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
717	            const int s = idx / vit::kD, j = idx % vit::kD;
718	            sm->final_in[s][j] = sm->dh[s][j];
719	        }
720	        __syncthreads();
721	        vit_recompute_layer(w, li, sm);   // fills qkv,x1,ff0,gact,attn,ctx(=r2),caches
722	        // Restore dh (grad wrt h2 = n2 output).
723	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
724	            const int s = idx / vit::kD, j = idx % vit::kD;
725	            sm->dh[s][j] = sm->final_in[s][j];
726	        }
727	        __syncthreads();
728	        // n2 backward: dh -> dr2 (into ctx), accumulate n2 gamma/beta.
729	        vit_layernorm_bwd(&sm->dh[0][0], &sm->n2_xhat[0][0], &sm->n2_inv[0],
730	                          L.n2_w, &sm->ctx[0][0], G.n2_w, G.n2_b, sm->red, true);
731	        // r2 = x1 + ff2 -> dx1 (residual) := dr2 into fn_xhat; dr2 stays in ctx.
732	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
733	            const int s = idx / vit::kD, j = idx % vit::kD;
734	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx1 := dr2 (residual part)
735	        }
736	        __syncthreads();
737	        // ff.2 backward. dW_ff2 += dr2^T @ g; db_ff2 += Σ dr2; then dff0 written
738	        // OVER gact (its forward value consumed by the dW GEMM first).
739	        {
740	            const float* dY = &sm->ctx[0][0];   // dr2 [kSeq,d]
741	            const float* X = &sm->gact[0][0];   // g [kSeq,4d]
742	            const int wtot = vit::kD * vit::kDff;
743	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
744	                const int o = idx / vit::kDff, i = idx % vit::kDff;
745	                float acc = 0.0f;
746	                #pragma unroll
747	                for (int s = 0; s < vit::kSeq; ++s)
748	                    acc += dY[s * vit::kD + o] * X[s * vit::kDff + i];
749	                G.ff2_w[(int64_t)o * vit::kDff + i] += acc;
750	            }
751	            for (int o = threadIdx.x; o < vit::kD; o += blockDim.x) {
752	                float acc = 0.0f;
753	                #pragma unroll
754	                for (int s = 0; s < vit::kSeq; ++s) acc += dY[s * vit::kD + o];
755	                G.ff2_b[o] += acc;
756	            }
757	            __syncthreads();
758	            const int xtot = vit::kSeq * vit::kDff;
759	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
760	                const int s = idx / vit::kDff, i = idx % vit::kDff;
761	                float dg = 0.0f;
762	                for (int o = 0; o < vit::kD; ++o)
763	                    dg += dY[s * vit::kD + o] * L.ff2_w[(int64_t)o * vit::kDff + i];
764	                sm->gact[s][i] = dg * vit_gelu_grad(sm->ff0[s][i]);  // gact := dff0
765	            }
766	            __syncthreads();
767	        }
768	        // ff.0 backward: dY=dff0(=gact), X=x1 -> dW ff0, db ff0, dx1 += dff0 @ ff0_w.
769	        {
770	            const float* dY = &sm->gact[0][0];   // dff0 [kSeq,4d]
771	            const float* X = &sm->x1[0][0];      // x1 [kSeq,d]
772	            const int wtot = vit::kDff * vit::kD;
773	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
774	                const int o = idx / vit::kD, i = idx % vit::kD;
775	                float acc = 0.0f;
776	                #pragma unroll
777	                for (int s = 0; s < vit::kSeq; ++s)
778	                    acc += dY[s * vit::kDff + o] * X[s * vit::kD + i];
779	                G.ff0_w[(int64_t)o * vit::kD + i] += acc;
780	            }
781	            for (int o = threadIdx.x; o < vit::kDff; o += blockDim.x) {
782	                float acc = 0.0f;
783	                #pragma unroll
784	                for (int s = 0; s < vit::kSeq; ++s) acc += dY[s * vit::kDff + o];
785	                G.ff0_b[o] += acc;
786	            }
787	            __syncthreads();
788	            const int xtot = vit::kSeq * vit::kD;
789	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
790	                const int s = idx / vit::kD, i = idx % vit::kD;
791	                float acc = 0.0f;
792	                for (int o = 0; o < vit::kDff; ++o)
793	                    acc += dY[s * vit::kDff + o] * L.ff0_w[(int64_t)o * vit::kD + i];
794	                sm->fn_xhat[s][i] += acc;   // dx1 += FFN path
795	            }
796	            __syncthreads();
797	        }
798	        // dx1 (in fn_xhat) -> n1 backward -> dr1 (into ctx). accumulate n1 g/b.
799	        vit_layernorm_bwd(&sm->fn_xhat[0][0], &sm->n1_xhat[0][0], &sm->n1_inv[0],
800	                          L.n1_w, &sm->ctx[0][0], G.n1_w, G.n1_b, sm->red, true);
801	        // r1 = x_in + a -> da = dr1; dx_in := dr1 (residual) into fn_xhat. da in ctx.
802	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
803	            const int s = idx / vit::kD, j = idx % vit::kD;
804	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx_in := dr1 (residual)
805	        }
806	        __syncthreads();
807	        // Rebuild ctx_fwd (attention context) from attn + v into x1 (x1 free —
808	        // ff bwd done). ctx_fwd[qi,col] = Σ_kj attn[hh][qi][kj] * v[kj, col].
809	        for (int r = threadIdx.x; r < vit::kSeq * vit::kD; r += blockDim.x) {
810	            const int qi = r / vit::kD, col = r % vit::kD;
811	            const int hh = col / vit::kDhead, t = col % vit::kDhead;
812	            float acc = 0.0f;
813	            #pragma unroll
814	            for (int kj = 0; kj < vit::kSeq; ++kj)   // FULL: all kj
815	                acc += sm->attn[hh][qi][kj]
816	                     * sm->qkv[kj][2 * vit::kD + hh * vit::kDhead + t];
817	            sm->x1[qi][col] = acc;   // x1 := ctx_fwd
818	        }
819	        __syncthreads();
820	        // da is in ctx. out_proj bwd: dW_out += da^T @ ctx_fwd(x1); db_out += Σ da;
821	        // dctx = da @ out_w -> ff0 scratch (free). dctx (logical width kD) MUST be
822	        // written at ff0's DECLARED row stride (kDff) — the attention-bwd readers
823	        // below (A at 824, B at 839) read it as sm->ff0[qi][col]; a packed
824	        // (kD-stride) write would fill only row 0's first 128 floats and leave
825	        // rows 1..16 reading stale recomputed pre-GELU values.
826	        vit_linear_bwd(&sm->ctx[0][0], &sm->x1[0][0], L.out_w, vit::kD, vit::kD,
827	                       G.out_w, G.out_b, &sm->ff0[0][0], /*set_dx=*/true, // dctx->ff0
828	                       /*ldY=*/vit::kD, /*ldX=*/vit::kD, /*ldDX=*/vit::kDff);
829	        // ── FULL attention backward (3 synced passes; `attn` read by A & B, never
830	        //    overwritten — dscores go to `dsc`). dctx [kSeq,d] in ff0; v/k/q in
831	        //    qkv[:,2d:3d]/[:,d:2d]/[:,0:d]; dqkv built into gact[:, :3d]. ────────
832	        const float scale = vit::attn_scale();
833	        // A: dv into gact[:, 2d:3d]. dv[kj,qoff+t]=Σ_{qi} attn[hh][qi][kj]
834	        //    * dctx[qi, qoff+t].  (FULL: all qi. Owner: thread per (kj, head, t).)
835	        for (int r = threadIdx.x; r < vit::kSeq * vit::kHeads * vit::kDhead;
836	             r += blockDim.x) {
837	            const int kj = r / (vit::kHeads * vit::kDhead);
838	            const int rem = r % (vit::kHeads * vit::kDhead);
839	            const int hh = rem / vit::kDhead, t = rem % vit::kDhead;
840	            const int qoff = hh * vit::kDhead;
841	            float acc = 0.0f;
842	            #pragma unroll
843	            for (int qi = 0; qi < vit::kSeq; ++qi)   // FULL (no causal qi>=kj)
844	                acc += sm->attn[hh][qi][kj] * sm->ff0[qi][qoff + t];
845	            sm->gact[kj][2 * vit::kD + qoff + t] = acc;   // dv block
846	        }
847	        __syncthreads();
848	        // B: dscores into dsc. datt[hh,qi,kj]=Σ_t dctx[qi,qoff+t]*v[kj,qoff+t];
849	        //    ds = attn*(datt - Σ_k datt*attn)*scale  (FULL: all kj).
850	        for (int r = threadIdx.x; r < vit::kHeads * vit::kSeq; r += blockDim.x) {
851	            const int hh = r / vit::kSeq, qi = r % vit::kSeq;
852	            const int qoff = hh * vit::kDhead;
853	            float datt[vit::kSeq];
854	            #pragma unroll
855	            for (int kj = 0; kj < vit::kSeq; ++kj) {
856	                float acc = 0.0f;
857	                #pragma unroll
858	                for (int t = 0; t < vit::kDhead; ++t)
859	                    acc += sm->ff0[qi][qoff + t]
860	                         * sm->qkv[kj][2 * vit::kD + qoff + t];
861	                datt[kj] = acc;
862	            }
863	            float dot = 0.0f;
864	            #pragma unroll
865	            for (int kj = 0; kj < vit::kSeq; ++kj) dot += datt[kj] * sm->attn[hh][qi][kj];
866	            #pragma unroll
867	            for (int kj = 0; kj < vit::kSeq; ++kj) {
868	                float a = sm->attn[hh][qi][kj];
869	                sm->dsc[hh][qi][kj] = a * (datt[kj] - dot) * scale;
870	            }
871	        }
872	        __syncthreads();
873	        // C: dq into gact[:,0:d], dk into gact[:,d:2d].  (FULL: all kj/qi.)
874	        for (int r = threadIdx.x; r < vit::kSeq * vit::kHeads * vit::kDhead;
875	             r += blockDim.x) {
876	            const int pos = r / (vit::kHeads * vit::kDhead);
877	            const int rem = r % (vit::kHeads * vit::kDhead);
878	            const int hh = rem / vit::kDhead, t = rem % vit::kDhead;
879	            const int qoff = hh * vit::kDhead;
880	            float dq = 0.0f, dk = 0.0f;
881	            #pragma unroll
882	            for (int kj = 0; kj < vit::kSeq; ++kj) {
883	                dq += sm->dsc[hh][pos][kj] * sm->qkv[kj][vit::kD + qoff + t];
884	                dk += sm->dsc[hh][kj][pos] * sm->qkv[kj][qoff + t];
885	            }
886	            sm->gact[pos][qoff + t] = dq;            // dq block (gact[:,0:d])
887	            sm->gact[pos][vit::kD + qoff + t] = dk;  // dk block (gact[:,d:2d])
888	        }
889	        __syncthreads();
890	        // in_proj backward: dqkv (gact[:, :3d]) -> dW in, db in, dx_in += dqkv @ in_w.
891	        // dqkv was written 2D (sm->gact[pos][col]) at gact's DECLARED width kDff, so
892	        // dY's row stride is kDff — a packed (3d=384) read would walk off row 0 into
893	        // the stale dq/dk/dv values left in gact[0][384:512]. X/dx_out (layer_in,
894	        // fn_xhat) are genuinely kD-wide, so ldX=ldDX=kD.
895	        vit_linear_bwd(&sm->gact[0][0], &sm->layer_in[li][0][0], L.in_w,
896	                       vit::kD, 3 * vit::kD, G.in_w, G.in_b,
897	                       &sm->fn_xhat[0][0], /*set_dx=*/false,   // dx_in += attn path
898	                       /*ldY=*/vit::kDff, /*ldX=*/vit::kD, /*ldDX=*/vit::kD);
899	        // dh for the previous layer = dx_in (in fn_xhat). Move to dh.
900	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
901	            const int s = idx / vit::kD, j = idx % vit::kD;
902	            sm->dh[s][j] = sm->fn_xhat[s][j];
903	        }
904	        __syncthreads();
905	    }
906	
907	    // ── embedding backward: dh = grad wrt h0 [kSeq,d] (post-cat, pre-pos-add).
908	    //    pos.weight[s] += dh[s] (ALL 17 positions); cls_token += dh[0]; patch_proj
909	    //    weight/bias from rows 1..16 against the live patch pixels. Owner-thread:
910	    //    thread owns column j (for pos/cls) or (o,i)/(o) (for patch). ───────────
911	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
912	        #pragma unroll
913	        for (int s = 0; s < vit::kSeq; ++s)
914	            g.pos[(int64_t)s * vit::kD + j] += sm->dh[s][j];   // pos (all rows)
915	        g.cls[j] += sm->dh[0][j];                              // cls_token (row 0)
916	    }
917	    __syncthreads();
918	    // patch_proj.weight [d, patch] and bias [d]: owner thread per (o,i) / per o;
919	    // sum over the 16 patch positions (sequential), reading sm->patch.
920	    const int pwtot = vit::kD * vit::kPatch;
921	    for (int idx = threadIdx.x; idx < pwtot; idx += blockDim.x) {
922	        const int o = idx / vit::kPatch, i = idx % vit::kPatch;
923	        float acc = 0.0f;
924	        #pragma unroll
925	        for (int p = 0; p < vit::kNPatch; ++p)
926	            acc += sm->dh[1 + p][o] * sm->patch[p][i];
927	        g.patch_w[(int64_t)o * vit::kPatch + i] += acc;
928	    }
929	    for (int o = threadIdx.x; o < vit::kD; o += blockDim.x) {
930	        float acc = 0.0f;
931	        #pragma unroll
932	        for (int p = 0; p < vit::kNPatch; ++p) acc += sm->dh[1 + p][o];
933	        g.patch_b[o] += acc;
934	    }
935	    __syncthreads();
936	}
