180	// =========================================================================
181	//  Warp-level u32 sum reduction (§4.1 PTX maximization).
182	//  Integer reductions use the single-instruction `redux.sync.add.u32`
183	//  warp collective on Ampere/Hopper (sm_80+), which replaces the 5-step
184	//  shuffle-xor butterfly with one instruction. Every lane in the (fully
185	//  active) warp receives the full-warp sum. A shuffle-tree fallback keeps
186	//  the helper compiling/working on pre-Ampere arches in the codegen matrix.
187	//
188	//  NOTE: integer-only. FLOAT redux (`redux.sync.{add,min,max}.f32`) is
189	//  Blackwell-only (sm_100+) and out of scope — float reductions stay on the
190	//  shuffle tree (warp_reduce_sum_f32 above).
191	// =========================================================================
192	
193	__device__ __forceinline__ unsigned warp_reduce_add_u32(unsigned v) {
194	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
195	    unsigned r;
196	    asm volatile("redux.sync.add.u32 %0, %1, 0xffffffff;" : "=r"(r) : "r"(v));
197	    return r;  // every lane gets the full-warp sum
198	#else
199	    // shuffle-tree fallback (pre-Ampere)
200	    for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffff, v, o);
201	    return v;
202	#endif
203	}
204	
205	// =========================================================================
206	//  Block-level u32 sum reduction: warp reduce + shared-memory tree + warp
207	//  reduce. Mirrors block_reduce_sum_f32 exactly (32 u32 of smem, one per
208	//  warp; same __syncthreads placement) but uses the redux.sync warp reducer.
209	// =========================================================================
210	
211	__device__ __forceinline__ unsigned block_reduce_add_u32(unsigned v) {
212	    __shared__ unsigned smem[32];
213	    const int tid = threadIdx.x;
214	    const int warp = tid / 32;
215	    const int lane = tid & 31;
216	
217	    unsigned w = warp_reduce_add_u32(v);
218	    if (lane == 0) smem[warp] = w;
219	    __syncthreads();
220	
221	    int n_warps = (blockDim.x + 31) / 32;
222	    if (warp == 0) {
223	        unsigned x = (lane < n_warps) ? smem[lane] : 0u;
224	        x = warp_reduce_add_u32(x);
225	        if (lane == 0) smem[0] = x;
226	    }
227	    __syncthreads();
228	    return smem[0];
229	}
